import{_ as s,o as t,c as o,a3 as r}from"./chunks/framework.BlfGB29P.js";const h=JSON.parse('{"title":"User guide","description":"","frontmatter":{},"headers":[],"relativePath":"en/projects/logic-studio/user-guide.md","filePath":"en/projects/logic-studio/user-guide.md","lastUpdated":1795175749000}'),i={name:"en/projects/logic-studio/user-guide.md"};function a(n,e,l,u,c,d){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="user-guide" tabindex="-1">User guide <a class="header-anchor" href="#user-guide" aria-label="Permalink to &quot;User guide&quot;">​</a></h1><p>This guide is for beginners. Open HA Logic Studio Pro in Home Assistant, select <strong>New project</strong>, then choose an editor and a name. For the examples, create a toggle helper under <strong>Settings → Devices &amp; services → Helpers</strong>. The examples use <code>input_boolean.studio_test</code>. Use your helper’s actual entity ID.</p><h2 id="which-editor-should-i-use" tabindex="-1">Which editor should I use? <a class="header-anchor" href="#which-editor-should-i-use" aria-label="Permalink to &quot;Which editor should I use?&quot;">​</a></h2><ul><li><strong>Function plan</strong> for signals, timers and counters on a canvas.</li><li><strong>Rules</strong> for IF → THEN or ELSE rules.</li><li><strong>Blocks A</strong> to assemble Home Assistant automations from blocks.</li><li><strong>Blocks JS</strong> to assemble scripts from blocks and import ioBroker projects.</li><li><strong>JavaScript</strong> or <strong>TypeScript</strong> to write scripts.</li><li><strong>HA-YAML</strong> to edit, check and visualize automations and scripts.</li></ul><h2 id="common-controls" tabindex="-1">Common controls <a class="header-anchor" href="#common-controls" aria-label="Permalink to &quot;Common controls&quot;">​</a></h2><ul><li><strong>Save</strong> stores changes. Orange indicates pending edits. Gray means there is nothing to save.</li><li><strong>Cancel</strong> discards edits made since the last save and restores the saved version.</li><li><strong>Test run</strong> uses simulation in the script editors. In the function plan, you can toggle simulated inputs.</li><li><strong>Play</strong> starts the saved version in the runtime for Function plan, Blocks JS, JavaScript and TypeScript. Approved HA actions can change real entities there. <strong>Stop</strong> ends the run.</li><li><strong>Check</strong> shows problems before exporting or running. <strong>Export</strong> creates a file you can use in Home Assistant.</li><li><strong>Expert mode</strong> in the project menu shows additional editor tools. The <strong>Log</strong> shows output and errors for the open project.</li></ul><h2 id="editors" tabindex="-1">Editors <a class="header-anchor" href="#editors" aria-label="Permalink to &quot;Editors&quot;">​</a></h2><ul><li><a href="./user-guide/function-plan">Function plan</a></li><li><a href="./user-guide/rules">Rules</a></li><li><a href="./user-guide/blocks-a">Blocks A</a></li><li><a href="./user-guide/blocks-js">Blocks JS</a></li><li><a href="./user-guide/javascript">JavaScript</a></li><li><a href="./user-guide/typescript">TypeScript</a></li><li><a href="./user-guide/ha-yaml">HA-YAML</a></li><li><a href="./user-guide/feedback">Report issues and contribute</a></li></ul>',8)])])}const p=s(i,[["render",a]]);export{h as __pageData,p as default};
